CREATE OR REPLACE VIEW `v_class_marks` AS SELECT `m`.`id` AS `id`, `m`.`class_id` AS `class_id`, `c`.`subject_id` AS `subject_id`, `c`.`kind` AS `class_kind`, `c`.`name` AS `class_name`, `m`.`group_id` AS `group_id`, `g`.`name` AS `group_name`, `m`.`kind` AS `kind`, `m`.`note` AS `note`, `m`.`version` AS `version`, `m`.`created_by` AS `created_by`, `m`.`created_at` AS `created_at`, `m`.`updated_at` AS `updated_at` FROM `class_marks` `m` JOIN `classes` `c` ON `c`.`id` = `m`.`class_id` LEFT JOIN `class_groups` `g` ON `g`.`id` = `m`.`group_id` WHERE `m`.`deleted_at` IS NULL;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_class_mark_skips` AS SELECT `k`.`id` AS `id`, `k`.`mark_id` AS `mark_id`, `k`.`on_date` AS `on_date`, `k`.`created_by` AS `created_by`, `k`.`created_at` AS `created_at` FROM `class_mark_skips` `k` JOIN `class_marks` `m` ON `m`.`id` = `k`.`mark_id` WHERE `m`.`deleted_at` IS NULL;--> statement-breakpoint
CREATE OR REPLACE VIEW `v_class_sessions` AS SELECT `cs`.`id` AS `id`, `cs`.`starts_at` AS `starts_at`, `cs`.`ends_at` AS `ends_at`, `cs`.`subject_id` AS `subject_id`, `s`.`name` AS `subject_name`, `cs`.`class_id` AS `class_id`, `c`.`kind` AS `class_kind`, `c`.`name` AS `class_name`, `cs`.`group_id` AS `group_id`, `g`.`name` AS `group_name`, `cs`.`lecturer_id` AS `lecturer_id`, `l`.`name` AS `lecturer_name`, `cs`.`room` AS `room`, `cs`.`label` AS `label`, `cs`.`status` AS `status`, `cs`.`kind` AS `kind` FROM `class_sessions` `cs` JOIN `subjects` `s` ON `s`.`id` = `cs`.`subject_id` LEFT JOIN `classes` `c` ON `c`.`id` = `cs`.`class_id` LEFT JOIN `class_groups` `g` ON `g`.`id` = `cs`.`group_id` LEFT JOIN `lecturers` `l` ON `l`.`id` = `cs`.`lecturer_id`;
